-- Real-profile authorization and workflow tests. Every task, checklist and notification rolls back.
begin;
select set_config('request.jwt.claim.sub',(select id::text from public.profiles where active and personnel_category='ceo' limit 1),true);
set local role authenticated;
do $$
declare shareholder uuid;other_shareholder uuid;ceo uuid;manager uuid;supervisor uuid;operator_id uuid;plant uuid;root uuid;mt uuid;st uuid;ot uuid;extra uuid;cursor_id bigint;check_id uuid;before_count integer;after_count integer;failed boolean;
begin
 select id into shareholder from public.profiles where active and personnel_category='shareholder' order by full_name limit 1;
 select id into other_shareholder from public.profiles where active and personnel_category='shareholder' and id<>shareholder limit 1;
 select ceo_user_id into ceo from public.task_governance;
 select p.id into operator_id from public.profiles p where p.active and p.role='operator' and p.full_name not like '[MOC]%' order by p.created_at limit 1;
 select corporate_manager_id into supervisor from public.profiles where id=operator_id;
 select corporate_manager_id into manager from public.profiles where id=supervisor;
 select business_unit_id into plant from public.user_unit_access where user_id=operator_id limit 1;
 if shareholder is null or ceo is null or manager is null or supervisor is null or operator_id is null then raise exception 'Required real hierarchy not configured';end if;
 if not private.todo_can_assign(shareholder,ceo) or private.todo_can_assign(shareholder,manager) or private.todo_can_assign(shareholder,supervisor) or private.todo_can_assign(shareholder,operator_id) then raise exception 'Committee hierarchy failed';end if;
 if not private.todo_can_assign(ceo,manager) or not private.todo_can_assign(ceo,supervisor) or private.todo_can_assign(ceo,operator_id) then raise exception 'CEO hierarchy failed';end if;
 if not private.todo_can_assign(manager,supervisor) or private.todo_can_assign(manager,operator_id) then raise exception 'Manager hierarchy failed';end if;
 if not private.todo_can_assign(supervisor,operator_id) or private.todo_can_assign(operator_id,supervisor) then raise exception 'Supervisor hierarchy failed';end if;
 perform set_config('request.jwt.claim.sub',shareholder::text,true);
 root:=public.create_operation_task(jsonb_build_object('title','TRANSIENT-TODO committee','assigned_to',ceo,'due_at',now()));
 perform set_config('request.jwt.claim.sub',ceo::text,true);
 mt:=public.create_operation_task(jsonb_build_object('title','TRANSIENT-TODO manager','assigned_to',manager,'parent_task_id',root,'due_at',now()));
 perform set_config('request.jwt.claim.sub',manager::text,true);
 st:=public.create_operation_task(jsonb_build_object('title','TRANSIENT-TODO supervisor','assigned_to',supervisor,'parent_task_id',mt,'business_unit_id',plant,'due_at',now()));
 failed:=false;begin perform public.create_operation_task(jsonb_build_object('title','BLOCKED direct operator','assigned_to',operator_id,'due_at',now()));exception when raise_exception then failed:=true;end;if not failed then raise exception 'Manager bypassed hierarchy';end if;
 perform set_config('request.jwt.claim.sub',supervisor::text,true);
 ot:=public.create_operation_task(jsonb_build_object('title','TRANSIENT-TODO operator','assigned_to',operator_id,'business_unit_id',plant,'due_at',now(),'checklist',jsonb_build_array(jsonb_build_object('label','Inspect safely','required',true))));
 select last_activity_id into cursor_id from public.operation_tasks where id=ot;
 perform public.link_operation_task(ot,st,cursor_id);
 if not exists(select 1 from public.operation_tasks where id=ot and parent_task_id=st) then raise exception 'Existing task link failed';end if;
 perform set_config('request.jwt.claim.sub',operator_id::text,true);
 if exists(select 1 from public.operation_tasks where id in(root,mt,st)) then raise exception 'Operator sees leadership tasks';end if;
 if not exists(select 1 from public.operation_task_inbox where id=ot and has_updates) then raise exception 'Operator inbox unavailable';end if;
 select last_activity_id into cursor_id from public.operation_tasks where id=ot;
 perform public.mark_operation_task_seen(ot,cursor_id);
 if exists(select 1 from public.operation_task_inbox where id=ot and has_updates) then raise exception 'Read cursor did not clear seen activity';end if;
 perform public.update_operation_task(ot,'Inspected the mixer',30,'in_progress','[]',cursor_id);
 failed:=false;begin perform public.update_operation_task(ot,'Stale overwrite',20,'in_progress','[]',cursor_id);exception when raise_exception then failed:=true;end;if not failed then raise exception 'Stale write accepted';end if;
 failed:=false;begin perform public.update_operation_task(ot,'Missing required checklist',100,'completion_requested','[]');exception when raise_exception then failed:=true;end;if not failed then raise exception 'Required checklist bypassed';end if;
 select id into check_id from public.operation_task_checks where task_id=ot;
 perform public.update_operation_task(ot,'All steps completed',100,'completion_requested',jsonb_build_array(jsonb_build_object('id',check_id,'done',true)));
 failed:=false;begin perform public.review_operation_task(ot,'approve','Self approval');exception when raise_exception then failed:=true;end;if not failed then raise exception 'Operator approved own task';end if;
 failed:=false;begin update public.operation_tasks set status='completed' where id=ot;exception when insufficient_privilege then failed:=true;end;if not failed then raise exception 'Direct table write allowed';end if;
 perform set_config('request.jwt.claim.sub',supervisor::text,true);
 if not exists(select 1 from public.operation_task_inbox where id=ot and has_updates) then raise exception 'Supervisor update badge missing';end if;
 failed:=false;begin perform public.update_operation_task(st,'Parent still has active child',100,'completion_requested','[]');exception when raise_exception then failed:=true;end;if not failed then raise exception 'Parent completed before child';end if;
 perform public.review_operation_task(ot,'return','Please confirm the result');
 perform set_config('request.jwt.claim.sub',operator_id::text,true);
 if not exists(select 1 from public.operation_tasks where id=ot and status='in_progress' and progress=99) then raise exception 'Return did not preserve progress';end if;
 perform public.update_operation_task(ot,'Result confirmed',100,'completion_requested','[]');
 perform set_config('request.jwt.claim.sub',supervisor::text,true);
 perform public.review_operation_task(ot,'approve','Confirmed complete');
 if not exists(select 1 from public.operation_tasks where id=ot and status='completed' and completed_at is not null) then raise exception 'Completion archive failed';end if;
 perform set_config('request.jwt.claim.sub',shareholder::text,true);
 if not exists(select 1 from public.operation_task_inbox where id=root and has_updates and progress=0 and status='pending') then raise exception 'Linked progress missing or parent falsely completed';end if;
 if not exists(select 1 from public.operation_task_activity where task_id=root and source_task_id=ot and event_type='linked_progress' and message like '%Inspected%') then raise exception 'Deep propagation failed';end if;
 select last_activity_id into cursor_id from public.operation_tasks where id=root;
 perform public.mark_operation_task_seen(root,cursor_id);
 perform set_config('request.jwt.claim.sub',operator_id::text,true);
 perform public.update_operation_task(ot,'Additional archived note',null,'note','[]');
 perform set_config('request.jwt.claim.sub',shareholder::text,true);
 perform public.mark_operation_task_seen(root,cursor_id);
 if not exists(select 1 from public.operation_task_inbox where id=root and has_updates) then raise exception 'Old read cursor hid newer activity';end if;
 perform set_config('request.jwt.claim.sub',other_shareholder::text,true);
 if exists(select 1 from public.operation_tasks where id in(root,mt)) then raise exception 'Unrelated committee member sees corporate private tasks';end if;
 if not exists(select 1 from public.operation_tasks where id=ot) then raise exception 'Corporate leadership cannot inspect unit task activity';end if;
 perform set_config('request.jwt.claim.sub',manager::text,true);
 select count(*) into before_count from public.operation_tasks;
 perform public.refresh_operation_task_sources();
 select count(*) into after_count from public.operation_tasks;
 select count(*) into before_count from public.operation_task_activity;
 perform public.refresh_operation_task_sources();
 if (select count(*) from public.operation_task_activity)<>before_count then raise exception 'Repeated source refresh generated duplicate activity';end if;
 if has_function_privilege('anon','public.create_operation_task(jsonb)','execute') or has_table_privilege('authenticated','public.operation_tasks','update') then raise exception 'Unauthorized grants';end if;
 raise notice 'PASS hierarchy, linked progress, source idempotency, checklists, review, read cursors and RLS';
end $$;
rollback;

select 'PASS: hierarchy, delegation, badges, RLS, optimistic writes, checklist, review and idempotency; all fixtures rolled back' as result;
